<?php
declare(strict_types=1);
namespace App\Http\Controllers\Academic;
use App\Http\Controllers\Controller;use App\Http\Requests\Academic\SaveGradesRequest;use App\Models\{AcademicSubject,AcademicYear,Semester,StudentGrade};use App\Services\Academic\{AcademicAccessService,AcademicEntryService};use Illuminate\Http\{RedirectResponse,Request};use Illuminate\View\View;
class GradeController extends Controller {public function index(Request $r,AcademicAccessService $a):View{$year=$r->integer('academic_year_id')?:AcademicYear::where('is_active',true)->value('id');$semester=$r->integer('semester_id')?:Semester::where('academic_year_id',$year)->where('is_active',true)->value('id');$roomId=$r->integer('classroom_id');$subjectId=$r->integer('academic_subject_id');$rooms=$a->classrooms($r->user())->where('academic_year_id',$year)->get();$room=$roomId?$a->ensureClassroom($r->user(),$roomId):null;$students=$room?->students()->orderBy('full_name')->get()??collect();$grades=StudentGrade::where(['semester_id'=>$semester,'classroom_id'=>$roomId,'academic_subject_id'=>$subjectId])->get()->keyBy('student_id');return view('academic.grades.index',compact('year','semester','rooms','room','students','grades')+['years'=>AcademicYear::orderByDesc('starts_at')->get(),'semesters'=>Semester::where('academic_year_id',$year)->get(),'subjects'=>AcademicSubject::orderBy('sort_order')->orderBy('name')->get(),'subjectId'=>$subjectId]);}public function store(SaveGradesRequest $r,AcademicEntryService $s):RedirectResponse{$s->saveGrades($r);return back()->with('success','Daftar nilai berhasil disimpan.');}public function subject(Request $r):RedirectResponse{abort_unless($r->user()->can('academic-grades.manage'),403);$d=$r->validate(['id'=>'nullable|exists:academic_subjects,id','code'=>'nullable|string|max:30','name'=>'required|string|max:255','sort_order'=>'nullable|integer|min:0','is_active'=>'nullable|boolean']);$subject=AcademicSubject::find($d['id']??0);unset($d['id']);$d['is_active']=$r->boolean('is_active');$d[$subject?'updated_by':'created_by']=$r->user()->id;$subject?->update($d)??AcademicSubject::create($d);activity('akademik')->causedBy($r->user())->log($subject?'Mengubah mata pelajaran':'Menambah mata pelajaran');return back()->with('success','Mata pelajaran berhasil disimpan.');}}
